: "26aea7e3-b874-45c8-92e3-69d493e2d66d", "type": "concept", "title": "Chatbots"}, {"id": "36f6b47a-ab87-4ad9-b413-8abe5d485320", "type": "concept", "title": "Interview analysis"}, {"id": "c688aaff-7e1c-41d4-85d5-f45fe3ee042d", "type": "concept", "title": "Sourcing recommendations"}, {"id": "f1293688-f8b5-413b-b531-5f923fbf7cef", "type": "concept", "title": "Scheduling automation"}], "description": "Students learn what tools do and where humans remain accountable."}, {"id": "f4f63a3a-7954-4fbe-866e-383e2d5bde91", "type": "subtopic", "title": "Bias, accessibility, and legal risk", "children": [{"id": "d86606b9-8bfe-4e1e-9c38-08439856d772", "type": "concept", "title": "Training data"}, {"id": "cafa6359-8021-40e8-b39f-1a8f5f41d002", "type": "concept", "title": "Proxy variables"}, {"id": "90e25a7b-5313-4f2f-ba49-f57ce0742509", "type": "concept", "title": "Disability accommodation"}, {"id": "1ef2938c-afd2-4405-b9de-e1aa7175d36a", "type": "concept", "title": "Language bias"}, {"id": "8a2523ee-f162-481f-a47b-a76ce9a6616f", "type": "concept", "title": "Disparate impact"}, {"id": "3fd96124-9019-4a51-84a1-a60cadc449d9", "type": "concept", "title": "Vendor claims"}], "description": "This subtopic examines how tools can reproduce historical bias or create new barriers."}, {"id": "9838c128-c833-43b2-a7bf-49c51acf142a", "type": "subtopic", "title": "Governance and auditability", "children": [{"id": "ab6f3774-cc6d-4cf9-a972-cd83533768a4", "type": "concept", "title": "Vendor due diligence"}, {"id": "b2962110-6827-4950-a14e-69fb82207c81", "type": "concept", "title": "Validation evidence"}, {"id": "1dad8914-8f60-442d-859e-55702d3cf9c6", "type": "concept", "title": "Human review"}, {"id": "e4e4982c-5796-4e4e-8005-d6e44019e4c1", "type": "concept", "title": "Audit logs"}, {"id": "5ec4ccfa-aabc-4af1-b1d7-00a776dd4acb", "type": "concept", "title": "Explainability"}, {"id": "ba735f1e-58f2-4a49-826f-ced03dd6a0fe", "type": "concept", "title": "Candidate notice"}], "description": "Students learn practical controls for responsible use of hiring technology."}]}, {"id": "9c8ad582-5bd4-4d47-97f9-0aefcc183e36", "type": "topic", "title": "Staffing Plan Project and Hiring Decision Communication", "description": "The capstone requires students to synthesize workforce planning, job analysis, sourcing, assessment, analytics, compliance, candidate experience, and AI governance into a professional staffing recommendation.", "children": [{"id": "1ff055ac-f9c7-4e93-bcf3-1bf064897e40", "type": "subtopic", "title": "Staffing problem diagnosis", "children": [{"id": "00bc44ee-2605-47b9-8d97-0cc63dba5f05", "type": "concept", "title": "Role context"}, {"id": "e663a7ab-1010-4a0a-8922-a7ee9b5a85b8", "type": "concept", "title": "Stakeholder goals"}, {"id": "d7d98c0b-30e4-489e-851d-3645abde73a5", "type": "concept", "title": "Labor-market constraints"}, {"id": "81993ec7-c7ad-4cc2-a8ae-ea205166fd0d", "type": "concept", "title": "Diversity goals"}, {"id": "44db5dcf-9041-478d-8beb-ad5a0070b8a8", "type": "concept", "title": "Hiring volume"}, {"id": "4198b1fd-9d1d-4e3e-9fab-ff5854a2cd63", "type": "concept", "title": "Risk analysis"}], "description": "Students learn to define the talent problem before proposing tactics."}, {"id": "3936dac9-225b-4f3a-ae5a-e99fea74f2e5", "type": "subtopic", "title": "Integrated staffing plan", "children": [{"id": "76aa3bce-e2ec-4ea3-b593-73babcce2c3c", "type": "concept", "title": "Sourcing mix"}, {"id": "82a884ff-1ed6-4954-8257-1b351d32e8a4", "type": "concept", "title": "Selection stages"}, {"id": "ffb37fe0-7262-44e4-a6ce-3e7dd3a0dad9", "type": "concept", "title": "Interview guides"}, {"id": "381ed558-87a1-4543-b827-ff7729212120", "type": "concept", "title": "Assessment plan"}, {"id": "2517c3af-1826-4af7-9120-52627bbc7c8d", "type": "concept", "title": "Timeline"}, {"id": "8a3a49eb-c9d7-4715-aa78-e94fbe63f6dc", "type": "concept", "title": "Metrics"}], "description": "This subtopic turns course tools into a coherent plan that a hiring team could actually use."}, {"id": "aa15284d-e5ad-4cad-aab3-03d0573a4dde", "type": "subtopic", "title": "Executive communication", "children": [{"id": "196e0ff7-fd0a-4367-861c-ee308a1c9ab2", "type": "concept", "title": "Decision memo"}, {"id": "6899aa9d-f3c1-4a53-baf9-c959d326d3d8", "type": "concept", "title": "Tradeoffs"}, {"id": "cf9ed298-2d37-477f-a3c8-ea384ab3c838", "type": "concept", "title": "Assumptions"}, {"id": "28156a53-7694-4195-b95a-83c705cf9420", "type": "concept", "title": "Implementation steps"}, {"id": "60d9fce0-0b9b-4acc-8b0d-0f249831b200", "type": "concept", "title": "Governance checks"}, {"id": "9abfd90e-0b8f-4f4c-9247-712f0f47702b", "type": "concept", "title": "Success measures"}], "description": "Students practice explaining hiring recommendations concisely and defensibly."}]}], "dbBacked": true}$rseljson$::jsonb,
