update public.learning_paths
set
  title = 'Recruitment and Selection',
  goal = 'Recruitment and Selection',
  summary = 'This course prepares HR students to design recruiting and selection systems that are strategic, inclusive, evidence-based, legally defensible, and humane for candidates. Students learn workforce planning, job analysis, sourcing, employer branding, screening, structured interviewing, assessment methods, validity, adverse impact, candidate experience, hiring analytics, AI governance, and staffing-plan communication.',
  data = $rseljson${"slug": "recruitment-and-selection", "title": "Recruitment and Selection", "description": "This course prepares HR students to design recruiting and selection systems that are strategic, inclusive, evidence-based, legally defensible, and humane for candidates. Students learn workforce planning, job analysis, sourcing, employer branding, screening, structured interviewing, assessment methods, validity, adverse impact, candidate experience, hiring analytics, AI governance, and staffing-plan communication.", "topics": [{"id": "cfb178ce-c07b-42a7-9e2d-e5a8d5268bc6", "type": "topic", "title": "Strategic Workforce Planning and Staffing Alignment", "description": "Students learn to connect recruiting activity to business strategy, workforce demand, labor supply, and talent risk. The goal is to avoid treating hiring as a reactive transaction and instead design staffing plans that support organizational capability.", "children": [{"id": "c8e2860b-ff8f-4f3b-8fb4-7ad95c448499", "type": "subtopic", "title": "Demand forecasting", "children": [{"id": "35d4100d-608b-4b76-8662-dd17eaf6cb8e", "type": "concept", "title": "Headcount planning"}, {"id": "b9af46af-e6cb-4aec-bc78-f480aa3ba566", "type": "concept", "title": "Growth scenarios"}, {"id": "63b9398d-1ac6-4353-b136-763aedebb20e", "type": "concept", "title": "Replacement needs"}, {"id": "a506f0cf-6573-414c-9a14-8b31d9d8b4e0", "type": "concept", "title": "Seasonality"}, {"id": "59c75ab0-2511-4a65-b254-cf65ead29d7b", "type": "concept", "title": "Critical roles"}, {"id": "5e5df794-e97c-4361-ac7f-73a1be532fae", "type": "concept", "title": "Vacancy risk"}], "description": "This subtopic teaches students to estimate future talent needs from business goals and operational signals."}, {"id": "e2376ced-53ac-4de3-8853-dc68ebf03055", "type": "subtopic", "title": "Internal and external labor supply", "children": [{"id": "d8e20446-6e93-460f-8342-2a06db36b2d0", "type": "concept", "title": "Internal mobility"}, {"id": "53afb0fd-29a1-46de-84cd-e2f4d4474d9e", "type": "concept", "title": "Succession pools"}, {"id": "c871e7b4-113f-4495-bd50-4fb7cd279291", "type": "concept", "title": "External labor markets"}, {"id": "bbe32589-21b9-4765-94d8-83daf0501a00", "type": "concept", "title": "Skills availability"}, {"id": "3238d909-7f28-4d19-8779-d9db71733cbc", "type": "concept", "title": "Geographic constraints"}, {"id": "c20f0ea7-75b9-4399-805f-b15473323d11", "type": "concept", "title": "Remote talent pools"}], "description": "Students learn where talent can come from and how supply constraints shape realistic recruiting strategy."}, {"id": "9cd0ecc1-0366-4e43-9151-cda531f4e014", "type": "subtopic", "title": "Staffing strategy choices", "children": [{"id": "2051e60e-74c0-41dd-b2cc-c14082fbc867", "type": "concept", "title": "Build-versus-buy"}, {"id": "7b8d5dc5-d28e-4bd4-823e-0f5b691a9a07", "type": "concept", "title": "Make-or-buy skills"}, {"id": "7eecca25-4dbf-4bd2-bfab-6bbee6484d2d", "type": "concept", "title": "Contingent labor"}, {"id": "4aa8f919-54dc-4905-8c21-5bb4c0dac1f2", "type": "concept", "title": "Outsourcing"}, {"id": "81d79aff-be8d-48c7-9bb6-6db6f00bb958", "type": "concept", "title": "Automation impact"}, {"id": "ed44276d-daef-45a3-acc1-67b5e8638ca9", "type": "concept", "title": "Talent segmentation"}], "description": "The point is to make deliberate choices about when to build, buy, borrow, automate, or redeploy talent."}]}, {"id": "2e443e34-c71a-4e9b-8494-98463f07aa85", "type": "topic", "title": "Job Analysis, Competency Models, and Success Profiles", "description": "A rigorous selection system starts with a clear definition of the job and the evidence of success. Students learn to translate work into competencies, criteria, and defensible assessment targets.", "children": [{"id": "d5f4854d-2630-42d8-8fb0-671d35c27710", "type": "subtopic", "title": "Job analysis methods", "children": [{"id": "c7e88b78-8a0c-429a-9ebd-4bacabb599a6", "type": "concept", "title": "Interviews"}, {"id": "bead51fb-53de-425f-a2eb-122735934733", "type": "concept", "title": "Observation"}, {"id": "a88c8c3f-97fd-4397-817f-20fbb1fb9936", "type": "concept", "title": "Task inventories"}, {"id": "dfb52e08-ba93-4a82-a317-3351edba1b1d", "type": "concept", "title": "Critical incidents"}, {"id": "9a5ca215-2b3a-40b0-93e0-3f09bfa85f82", "type": "concept", "title": "Work diaries"}, {"id": "290a0004-7f8d-4a9e-baff-535e4e58e5f5", "type": "concept", "title": "O*NET research"}], "description": "Students practice gathering job information systematically rather than relying on vague manager preferences."}, {"id": "38f8674b-f826-4014-b857-4cdf6acfe354", "type": "subtopic", "title": "Competency modeling", "children": [{"id": "2ac754b9-39cc-4e16-8c0c-2e9363f22e84", "type": "concept", "title": "KSAOs"}, {"id": "d3dca936-5c69-4a55-8591-14e265833ab2", "type": "concept", "title": "Behavioral competencies"}, {"id": "16c063fd-3044-4e39-be14-e667ba5b6384", "type": "concept", "title": "Technical skills"}, {"id": "64e9b292-0712-4cd7-a9ed-8872d6388681", "type": "concept", "title": "Leadership competencies"}, {"id": "78eeaab7-ea44-4ae6-80b2-305aebcf5a5b", "type": "concept", "title": "Proficiency levels"}, {"id": "ff437096-a06e-4108-9014-0710ca57a9d4", "type": "concept", "title": "Essential versus preferred criteria"}], "description": "This subtopic shows how knowledge, skills, abilities, and behaviors become hiring criteria."}, {"id": "486faa8f-27c2-4f9a-8649-f36a47703b0d", "type": "subtopic", "title": "Success profiles and job documentation", "children": [{"id": "0d7056cc-df46-4370-8933-2bc7ef0b0dd3", "type": "concept", "title": "Job descriptions"}, {"id": "ad6f5da4-708d-4005-a2ea-846683f12ca6", "type": "concept", "title": "Role outcomes"}, {"id": "062d9e10-0318-429d-820e-e97bb3c51e30", "type": "concept", "title": "Minimum qualifications"}, {"id": "c0e3eedd-eae9-4e0e-9bb6-b32518e57878", "type": "concept", "title": "Selection criteria"}, {"id": "0824d3c4-e619-45b7-9116-f22e3e0aa064", "type": "concept", "title": "Performance indicators"}, {"id": "ba014bf1-cab1-4a93-bf05-1a227611cbf0", "type": "concept", "title": "Documentation standards"}], "description": "Students learn to create job profiles that support valid selection, inclusive sourcing, and clear candidate communication."}]}, {"id": "87f1edce-31bb-4772-ab7e-0444467ca277", "type": "topic", "title": "Legal, Ethical, and Inclusive Hiring Foundations", "description": "Recruitment and selection decisions affect opportunity, livelihood, and organizational risk. Students learn the legal and ethical guardrails that make hiring fair, inclusive, and defensible.", "children": [{"id": "3a83f132-cf98-4b42-9bc2-30336a3413c3", "type": "subtopic", "title": "Equal employment opportunity", "children": [{"id": "5ba0fd75-4589-4281-b682-c97ef7c911ea", "type": "concept", "title": "Title VII"}, {"id": "9baf54b6-4b8b-43c3-a5bd-64645a0b9e9f", "type": "concept", "title": "ADA"}, {"id": "87542d86-0093-4b97-8bf9-2cac3662d12d", "type": "concept", "title": "ADEA"}, {"id": "792a70f4-7e96-4b85-998f-c2bc4cbd88de", "type": "concept", "title": "Pregnancy discrimination"}, {"id": "70331ba8-4f22-4ddf-8bef-d0b7d2779c7b", "type": "concept", "title": "Retaliation"}, {"id": "195036be-aefa-49a4-a168-a76375207c7a", "type": "concept", "title": "Reasonable accommodation"}], "description": "Students learn how antidiscrimination principles apply across attraction, screening, assessment, interviewing, and offers."}, {"id": "cbbd1f7f-c814-4f6e-9afd-319555778e4d", "type": "subtopic", "title": "Hiring compliance and documentation", "children": [{"id": "b25f3901-c26c-4da2-a315-86618666255b", "type": "concept", "title": "Uniform Guidelines"}, {"id": "20eede16-a0d1-4810-9251-cfd39d7f2c20", "type": "concept", "title": "Recordkeeping"}, {"id": "641e523d-873b-4af4-8c38-3997875f04ec", "type": "concept", "title": "Selection procedure documentation"}, {"id": "dbb1f4ef-3195-435d-9d70-f469bc4bd626", "type": "concept", "title": "Background-check rules"}, {"id": "1d452fa3-4acd-4bd2-9aab-e1978381ab55", "type": "concept", "title": "FCRA basics"}, {"id": "0c2a209f-6b7f-4ab1-9ef6-dfdcc7bcb846", "type": "concept", "title": "I-9 handoff"}], "description": "This subtopic gives students the compliance habits needed to defend staffing decisions."}, {"id": "90f7234c-03c7-433d-9f3e-e83047a3e69a", "type": "subtopic", "title": "Ethical and inclusive decision making", "children": [{"id": "67f20104-af00-4d43-9605-da1e89ffe938", "type": "concept", "title": "Bias awareness"}, {"id": "778d9651-e09c-4b71-97f6-9168678f0abf", "type": "concept", "title": "Accessibility"}, {"id": "dca1958b-ddb2-4c5b-ae65-16dade68601d", "type": "concept", "title": "Pay transparency"}, {"id": "4b4362a9-9055-4d89-b0fd-af3e0692ffbe", "type": "concept", "title": "Candidate privacy"}, {"id": "f443821b-8500-454c-a910-aa098160bf95", "type": "concept", "title": "Nepotism and conflicts"}, {"id": "a9785332-f90f-431e-8f79-f544828f0bb4", "type": "concept", "title": "Fair chance hiring"}], "description": "Students learn to balance organizational needs with fairness, transparency, privacy, and candidate dignity."}]}, {"id": "f417b066-5daa-4e68-834c-ab7b3654ee55", "type": "topic", "title": "Labor Market Intelligence and Recruiting Analytics", "description": "Students learn to use labor-market data and recruiting metrics to choose realistic sources, set expectations, and improve hiring outcomes. The emphasis is interpretation, not dashboard decoration.", "children": [{"id": "496e1c17-4502-491a-9104-eccc490020ac", "type": "subtopic", "title": "Labor-market research", "children": [{"id": "a36c51e7-6fd7-4ae5-adbc-a08f3ddd40da", "type": "concept", "title": "BLS data"}, {"id": "16cc0da6-7e3b-471b-a981-d56185d6df83", "type": "concept", "title": "Indeed Hiring Lab"}, {"id": "d62beb4a-6678-4db8-bf7c-2a8e5ae3d521", "type": "concept", "title": "LinkedIn insights"}, {"id": "3abe1ffd-ddf8-4187-9609-4947900ad17c", "type": "concept", "title": "Compensation signals"}, {"id": "112fcac2-e6cc-491d-a72a-011ea550644f", "type": "concept", "title": "Competitor hiring"}, {"id": "6feccb3e-6b5e-4359-b9d6-a1ec4597c9aa", "type": "concept", "title": "Skill adjacencies"}], "description": "This subtopic teaches students to read market data before launching a search."}, {"id": "aa95b2a9-48f8-4c7b-a736-eeb2fec49b2c", "type": "subtopic", "title": "Recruiting funnel metrics", "children": [{"id": "e4f1b6f8-2e73-4c73-9e5a-704fa85be2aa", "type": "concept", "title": "Applicants"}, {"id": "6a7ea58b-1689-477b-bf11-ccec7d7b3634", "type": "concept", "title": "Screen pass rate"}, {"id": "b60f762c-d3bd-4931-85a2-0c665a85e296", "type": "concept", "title": "Interview conversion"}, {"id": "6220fa24-8041-4ebf-b6d3-d0d741185f2b", "type": "concept", "title": "Offer acceptance"}, {"id": "6ea6d34a-2e54-46d7-b7b0-41febee6a60e", "type": "concept", "title": "Time to fill"}, {"id": "ea654110-4c16-434a-a892-fc2de537ae96", "type": "concept", "title": "Source quality"}], "description": "Students learn how candidates move through the hiring process and where the process loses quality, speed, or equity."}, {"id": "23f4479d-efec-4fea-bc13-6ef09be2fa93", "type": "subtopic", "title": "Evidence-based recruiting decisions", "children": [{"id": "29728808-571c-4e01-9eaa-d8ad6670ad74", "type": "concept", "title": "Metric definitions"}, {"id": "3602a656-d834-4ac6-9e36-9b4073691c13", "type": "concept", "title": "Data quality"}, {"id": "9f9dc485-b31d-4b74-9cbc-016d0d4b002a", "type": "concept", "title": "Benchmarking"}, {"id": "32c55a2f-93df-48e3-a12d-70a9508f64e3", "type": "concept", "title": "Funnel diagnosis"}, {"id": "75672195-8704-4f4d-add4-8039926a0e11", "type": "concept", "title": "Cost per hire"}, {"id": "53689037-283d-47ab-8adb-2efc3eb2fc54", "type": "concept", "title": "Quality of hire cautions"}], "description": "The point is to use data to improve sourcing and selection without overclaiming what metrics prove."}]}, {"id": "8f959ff4-e37f-414f-87ff-4832a037b216", "type": "topic", "title": "Sourcing Strategy and Talent Pipeline Development", "description": "Sourcing is the practical discipline of finding qualified people before and during a search. Students learn how to build diverse, role-appropriate pipelines rather than waiting for applications.", "children": [{"id": "9cb68976-e71a-4e32-835b-c126b223f871", "type": "subtopic", "title": "Source selection", "children": [{"id": "eeb5a623-cbd8-4c42-b957-e476185c9e95", "type": "concept", "title": "Job boards"}, {"id": "cce74cd9-1a44-4b8b-9078-d00225707014", "type": "concept", "title": "Employee referrals"}, {"id": "dc44b556-4316-47a2-9d36-0f21d5522114", "type": "concept", "title": "Campus recruiting"}, {"id": "1ed56bef-368c-485c-a41f-cd1a445ea775", "type": "concept", "title": "Professional associations"}, {"id": "d7d3f877-93ed-45ec-a623-2ce8d766c67f", "type": "concept", "title": "Community partners"}, {"id": "8fa0425f-03b9-43ed-acd7-25ad00df3e25", "type": "concept", "title": "Niche talent communities"}], "description": "Students compare channels and choose sources that fit the role, labor market, and inclusion goals."}, {"id": "dbf075b5-4d0e-46f2-b54c-e0a1937b0ced", "type": "subtopic", "title": "Active sourcing", "children": [{"id": "dbdd764a-893b-4b84-b82c-b66cc8793f47", "type": "concept", "title": "Boolean search"}, {"id": "8ef46243-f8ee-4138-825b-ec20a3f30fae", "type": "concept", "title": "LinkedIn sourcing"}, {"id": "2c8514bf-c604-4de8-96d6-cde4dd593383", "type": "concept", "title": "Talent mapping"}, {"id": "6ff10985-e75a-41e5-a1ed-a4d4e857c14b", "type": "concept", "title": "Outreach messages"}, {"id": "9a85101c-b5c3-44c2-abac-e479e72d28f2", "type": "concept", "title": "Response tracking"}, {"id": "13ab7ba9-56e0-42db-b4e3-b926fc5e22f7", "type": "concept", "title": "Privacy boundaries"}], "description": "This subtopic introduces techniques for identifying and contacting potential candidates ethically and effectively."}, {"id": "170806d7-2f80-42b1-bd20-79713d66dfbe", "type": "subtopic", "title": "Pipeline management", "children": [{"id": "745c398d-c576-4a7f-909a-a3eb07974e19", "type": "concept", "title": "Talent CRM"}, {"id": "eb27a791-e938-4409-bc50-7fc38ec30b75", "type": "concept", "title": "Silver medalists"}, {"id": "8f336524-61ae-4681-9210-74ff77797beb", "type": "concept", "title": "Internship pipelines"}, {"id": "e1c3b274-b186-4731-bf0c-0cda5e1d562d", "type": "concept", "title": "Alumni networks"}, {"id": "936a8248-2120-4146-9cc0-23a4322cf44f", "type": "concept", "title": "Nurture campaigns"}, {"id": "700db477-8ffa-4a23-8b08-71ab1bb0af1d", "type": "concept", "title": "Pipeline health metrics"}], "description": "Students learn to maintain relationships and talent pools over time."}]}, {"id": "31d4fa34-d295-455e-bfe8-f205f992e681", "type": "topic", "title": "Employer Branding and Recruitment Marketing", "description": "Students learn how organizations signal their employee value proposition to target talent markets. The goal is honest, differentiated communication that attracts fit without overselling the workplace.", "children": [{"id": "c68e535a-f98c-42f4-9635-d5da578c5aa1", "type": "subtopic", "title": "Employee value proposition", "children": [{"id": "e99dbe31-537c-4c3f-a3ac-7a1b0e07cc3e", "type": "concept", "title": "Mission"}, {"id": "2d4d7c3f-24a0-4b6e-8547-56d0fd238e8c", "type": "concept", "title": "Rewards"}, {"id": "b08c1c5b-9573-4bcb-bfb4-81ad3d2aea5e", "type": "concept", "title": "Career growth"}, {"id": "c8c6665f-958e-4529-9616-fc4903fba463", "type": "concept", "title": "Culture"}, {"id": "7d5cfe28-697a-41e1-aeb3-abc1f40c6054", "type": "concept", "title": "Flexibility"}, {"id": "6acee688-c1ee-4dd2-a77f-6a16a9b30c29", "type": "concept", "title": "Belonging"}], "description": "This subtopic helps students identify what the organization credibly offers candidates."}, {"id": "da59bcb2-27ea-4bba-b8c6-af33620bd0bd", "type": "subtopic", "title": "Recruitment messaging", "children": [{"id": "d5da7bc2-3e7b-4593-822b-21c6a7982c0d", "type": "concept", "title": "Job posting language"}, {"id": "f4a1673f-32dd-4f95-abfd-4ae016f1175a", "type": "concept", "title": "Realistic job previews"}, {"id": "37c4c235-35fc-4158-81fc-5204c16bd93d", "type": "concept", "title": "Social recruiting"}, {"id": "9459eeb5-fa2a-4050-bb2e-c8695f6282e3", "type": "concept", "title": "Career pages"}, {"id": "f65d18bf-5935-43d0-b22d-c2365c1085e8", "type": "concept", "title": "Inclusive language"}, {"id": "df465ea1-eee3-4e0d-8f82-19c761ed78b6", "type": "concept", "title": "Message testing"}], "description": "Students learn to turn the value proposition into clear job ads, outreach, and campaign content."}, {"id": "7433428e-136b-4037-b177-de02bc495b07", "type": "subtopic", "title": "Brand credibility and measurement", "children": [{"id": "b0430119-3e04-4c10-a9dd-9269bda583c6", "type": "concept", "title": "Glassdoor signals"}, {"id": "45bef2e9-32bc-470e-8ca4-96dd0b725ef5", "type": "concept", "title": "Candidate surveys"}, {"id": "b5336491-0393-43fb-9f63-f921d186109b", "type": "concept", "title": "Brand awareness"}, {"id": "93751795-4fbd-4f2f-b49f-f59859591b82", "type": "concept", "title": "Application quality"}, {"id": "ec774586-ad6c-46e1-836d-c64dbe74ae50", "type": "concept", "title": "Authenticity"}, {"id": "0688187b-ae0f-4a13-9401-155f576243f4", "type": "concept", "title": "Expectation management"}], "description": "The point is to align promises with employee experience and track whether branding works."}]}, {"id": "7d9629e7-21f1-425b-86ef-d549d5167841", "type": "topic", "title": "Screening, Shortlisting, and Selection Workflow Design", "description": "Selection quality depends on process design. Students learn how to move candidates through a consistent, fair, efficient workflow from application review to finalist decision.", "children": [{"id": "85e63e9b-e9b4-4c21-bb5f-cfaec4165d38", "type": "subtopic", "title": "Screening criteria", "children": [{"id": "fcf621bd-9193-4bba-af90-08ba36fb4f14", "type": "concept", "title": "Minimum qualifications"}, {"id": "6c51f40d-8909-45d5-807b-364bd3ca7a59", "type": "concept", "title": "Preferred qualifications"}, {"id": "4cd8ede2-dc84-44c2-8be4-25248e7bc1b8", "type": "concept", "title": "Knockout questions"}, {"id": "279dbc08-22a9-4c5c-8545-7f93a73ed7f9", "type": "concept", "title": "Resume review rubrics"}, {"id": "901c79bc-5df2-4daf-b7a6-e001b6eefd73", "type": "concept", "title": "Transferable skills"}, {"id": "e46f355f-1138-4f94-ba53-9c3cd9dfae4e", "type": "concept", "title": "Overqualification concerns"}], "description": "Students learn to distinguish job-related screens from convenient but weak filters."}, {"id": "032d4a08-d9dd-43c5-bdd8-c94057613004", "type": "subtopic", "title": "Selection workflow", "children": [{"id": "e5f81cbd-60e1-488f-9ecf-4912bfede771", "type": "concept", "title": "Application review"}, {"id": "92385b7a-21bd-4bf8-8f76-7ff3029ea6ff", "type": "concept", "title": "Phone screens"}, {"id": "209b31b0-a058-4d16-b0b7-e600aacd8760", "type": "concept", "title": "Hiring manager screens"}, {"id": "f63f1203-14a2-4656-80bf-4690ecaa26f5", "type": "concept", "title": "Assessment stages"}, {"id": "527d406d-7977-4a8a-9a19-20859a2759e1", "type": "concept", "title": "Panel interviews"}, {"id": "f76b1ed2-52b0-4a0d-9ded-f0c62b3412a6", "type": "concept", "title": "Decision meetings"}], "description": "This subtopic teaches students to sequence assessment steps with purpose."}, {"id": "a5896dd0-5971-48b7-844f-3f912232329b", "type": "subtopic", "title": "Process governance", "children": [{"id": "baa766c0-1fe7-431e-9c7c-3fff7cea5b8f", "type": "concept", "title": "Role approvals"}, {"id": "1abaf33b-ee85-4792-95ae-e5066b2e721c", "type": "concept", "title": "Service-level agreements"}, {"id": "9d090370-20fa-4f80-aa81-88d29776e22f", "type": "concept", "title": "Evaluator training"}, {"id": "2d678fe9-c62b-4e4d-846f-76fd4a7d2a56", "type": "concept", "title": "Candidate status tracking"}, {"id": "2d98a74a-a771-44a3-bb21-898db438fa70", "type": "concept", "title": "Decision logs"}, {"id": "6ca91aa2-7963-4d6f-af12-f2cab38c3e6b", "type": "concept", "title": "Audit trails"}], "description": "Students learn how structure reduces drift, bias, delays, and inconsistent candidate treatment."}]}, {"id": "56e603b4-b90b-492a-ab19-bde89a5438bc", "type": "topic", "title": "Structured Interviews and Evaluation Rubrics", "description": "Structured interviews are one of the most important tools in modern selection. Students learn to design questions, probes, scoring guides, and interviewer practices that improve reliability and fairness.", "children": [{"id": "3e27e57d-d2f4-4904-b9ad-791a890e0785", "type": "subtopic", "title": "Behavioral and situational interview design", "children": [{"id": "bf4175bb-78a7-472a-9fad-d6dc4fe62d22", "type": "concept", "title": "Behavioral questions"}, {"id": "82da6250-4890-4512-9887-0472646fd73d", "type": "concept", "title": "Situational questions"}, {"id": "24009511-0a57-4a34-84e9-c2d2d008a68a", "type": "concept", "title": "Critical incidents"}, {"id": "5eed4028-213a-41d0-b16a-99ae21406742", "type": "concept", "title": "STAR method"}, {"id": "a2de58dc-b19c-491c-aec1-d6e8fd5d7c55", "type": "concept", "title": "Follow-up probes"}, {"id": "187afaa0-67fc-4203-ab1e-eb8e3ea443d7", "type": "concept", "title": "Question bank design"}], "description": "Students learn to ask questions tied directly to job requirements and future performance."}, {"id": "cb447654-cc0e-4b5b-b9e2-87047f24b8bb", "type": "subtopic", "title": "Scoring rubrics", "children": [{"id": "f6b64ccd-c0aa-4183-8b62-bf62f413483d", "type": "concept", "title": "Rating scales"}, {"id": "883cbbeb-230c-4c12-a558-f3f5c89ca5fd", "type": "concept", "title": "Behavioral anchors"}, {"id": "4af601c2-9773-49ce-a2fd-e15248f53001", "type": "concept", "title": "Evidence notes"}, {"id": "872e441b-cc2f-4e6e-8006-df323b63e0f1", "type": "concept", "title": "Consensus scoring"}, {"id": "bf20a934-bbf6-4440-ad26-d75517d86d18", "type": "concept", "title": "Rater calibration"}, {"id": "12ce8eb9-cf63-4ae6-8d