2e6", "type": "concept", "title": "Job simulations"}], "description": "Students compare tools by what they measure, how they are administered, and what evidence supports them."}, {"id": "12979c4d-f905-402c-a342-efea7ba4a863", "type": "subtopic", "title": "Work sample design", "children": [{"id": "5453bb2e-90b1-451f-a75e-d89a6cb1e817", "type": "concept", "title": "Case exercises"}, {"id": "25b39f80-655d-4983-8723-3eab1ce09f4e", "type": "concept", "title": "Writing samples"}, {"id": "5765dba2-8c96-4a12-a567-4a3bc83cf8cf", "type": "concept", "title": "Technical tasks"}, {"id": "bb7b6d22-714b-4712-a54e-8b2774cd8c2d", "type": "concept", "title": "Role plays"}, {"id": "f2cfe2a7-0b1d-44fd-bb20-82cacdbaca25", "type": "concept", "title": "Scoring guides"}, {"id": "0c884e9b-a6cd-43cc-977d-e4f3113056c3", "type": "concept", "title": "Time limits"}], "description": "This subtopic shows how realistic exercises can predict job performance while improving candidate understanding."}, {"id": "623a4ea5-b24a-4f07-b585-4568b713e81b", "type": "subtopic", "title": "Reference and background information", "children": [{"id": "c131b8f8-c25e-4997-84cd-f8c4324df7d0", "type": "concept", "title": "Reference checks"}, {"id": "43a8d8a0-1975-4760-8830-3003c254148c", "type": "concept", "title": "Credential verification"}, {"id": "215f741c-d8a6-437b-88be-c302eaf53564", "type": "concept", "title": "Background checks"}, {"id": "3395f0b4-b25e-4465-a2ea-aa450d475e80", "type": "concept", "title": "Social media cautions"}, {"id": "64776a78-dc5b-414d-a439-ea1c9c9556c0", "type": "concept", "title": "Consent"}, {"id": "0513301f-6a79-4aaf-b1fc-1001e6a31bae", "type": "concept", "title": "Consistency"}], "description": "Students learn the lawful and ethical use of information beyond interviews and tests."}]}, {"id": "ded25557-bfe5-4a01-a40c-1f9f86c8a738", "type": "topic", "title": "Validity, Reliability, Utility, and Adverse Impact", "description": "This section gives students the measurement backbone of selection. They learn why a tool must be job-related, consistent, useful, and monitored for unequal impact.", "children": [{"id": "84de757b-02d0-4980-9455-859dbc39c141", "type": "subtopic", "title": "Reliability and validity", "children": [{"id": "23c942ba-b6e8-466c-bdeb-20984cb54222", "type": "concept", "title": "Inter-rater reliability"}, {"id": "ad63b405-15e8-410c-9ee2-d56d092ae5af", "type": "concept", "title": "Test-retest reliability"}, {"id": "44a2ccb4-64af-45cd-9826-dce3ce57de9a", "type": "concept", "title": "Content validity"}, {"id": "3edcb127-6747-49b2-a944-9d194c62b622", "type": "concept", "title": "Criterion validity"}, {"id": "5551ab56-686b-4931-a2de-4f78d72f36e9", "type": "concept", "title": "Construct validity"}, {"id": "2b66e64d-cba1-4e58-bf36-624575f08e84", "type": "concept", "title": "Validation evidence"}], "description": "Students learn the core concepts that separate defensible assessment from guesswork."}, {"id": "bb66bb64-66ca-4e89-bad9-aec21e0810f0", "type": "subtopic", "title": "Selection utility", "children": [{"id": "3e616e1e-7053-4155-af6d-89c490c72246", "type": "concept", "title": "Base rates"}, {"id": "27f63f65-e65f-4da3-bf32-66b6949c746c", "type": "concept", "title": "Selection ratios"}, {"id": "cf60119a-f52b-40a8-967b-0185fd230aa6", "type": "concept", "title": "Predictive value"}, {"id": "cedcdcba-b234-4c99-b2e2-062a842c6351", "type": "concept", "title": "Cost of errors"}, {"id": "8ea207ed-eb5e-45a2-8471-c69c0bc9df94", "type": "concept", "title": "False positives"}, {"id": "43a283d1-8720-4a7c-9c72-bb667e785b29", "type": "concept", "title": "False negatives"}], "description": "This subtopic connects assessment quality to business outcomes and hiring tradeoffs."}, {"id": "06e54838-f4a9-498e-ab55-598e04c25634", "type": "subtopic", "title": "Adverse impact analysis", "children": [{"id": "f9ff4aba-a02a-4cb8-ac1a-064e53219de0", "type": "concept", "title": "Four-fifths rule"}, {"id": "2242e98b-221d-42c5-85e9-cc58449880d2", "type": "concept", "title": "Applicant-flow data"}, {"id": "a7033d0f-bb86-4c67-95e6-21b843c7462d", "type": "concept", "title": "Statistical significance basics"}, {"id": "72afb7d2-fa31-4cb6-8b23-32365b62b64a", "type": "concept", "title": "Alternative procedures"}, {"id": "5ed53546-6169-4a97-b6b6-03ad0d3264bc", "type": "concept", "title": "Business necessity"}, {"id": "4b9201a7-b3cb-4db0-a8a0-b40ba5b4086c", "type": "concept", "title": "Remediation planning"}], "description": "Students learn to identify and respond to selection patterns that disproportionately screen out protected groups."}]}, {"id": "8e2ada87-017d-4149-8a99-a71eebe37e20", "type": "topic", "title": "Candidate Experience, Offers, and Hiring Handoff", "description": "Recruitment is also an experience design problem. Students learn how communication, speed, transparency, negotiation, and onboarding handoff influence acceptance, trust, and employer reputation.", "children": [{"id": "eb6561d8-8be1-43e5-a062-8fac21ba6bf2", "type": "subtopic", "title": "Candidate communication", "children": [{"id": "3de8e512-bfe3-4916-9089-715d8882c736", "type": "concept", "title": "Status updates"}, {"id": "8ad331fe-d449-48a1-a208-63af65e28faf", "type": "concept", "title": "Timelines"}, {"id": "0b54899d-9fe5-4a3a-aac6-4fa34f70bcd2", "type": "concept", "title": "Rejection messages"}, {"id": "48871091-926c-455c-b42b-6d4aa5e58d91", "type": "concept", "title": "Feedback boundaries"}, {"id": "06274b48-e8f5-4f1d-ab94-535153747a39", "type": "concept", "title": "Accessibility"}, {"id": "f4febaff-75f9-4630-b9b5-da06e385484c", "type": "concept", "title": "Candidate FAQs"}], "description": "Students learn to keep candidates informed without sacrificing process integrity."}, {"id": "62a29af0-e998-4505-97d2-863062ec281a", "type": "subtopic", "title": "Offer strategy and negotiation", "children": [{"id": "66791bc9-765e-4628-b72e-ceb47cd2e6c1", "type": "concept", "title": "Offer approval"}, {"id": "34a2bb4d-b1b5-470f-bd35-1a2bd21957af", "type": "concept", "title": "Pay ranges"}, {"id": "c1f74015-da81-4c32-956f-12496be3bfcf", "type": "concept", "title": "Negotiation"}, {"id": "ded91257-7a84-4b6f-9ca5-9d0b22fc3b88", "type": "concept", "title": "Counteroffers"}, {"id": "4cf6cbd0-e004-4145-bee1-bdba1de9741b", "type": "concept", "title": "Offer letters"}, {"id": "ee0a286c-cbd4-4136-ad19-2a05df3edb22", "type": "concept", "title": "Start-date planning"}], "description": "This subtopic connects selection decisions to compensation, equity, and closing candidates."}, {"id": "68c85168-a997-44a0-a83a-6db1e80d320c", "type": "subtopic", "title": "Preboarding and onboarding handoff", "children": [{"id": "62b8c2b4-adb3-4d02-931e-2fc97af59706", "type": "concept", "title": "Background-check timing"}, {"id": "c8e456a0-82d9-49a8-be4c-dd3aece1e906", "type": "concept", "title": "I-9 and documentation"}, {"id": "94f327fa-8055-4086-9334-c1d80f612dbf", "type": "concept", "title": "Manager handoff"}, {"id": "74914916-030b-4cda-9967-2b30a1747279", "type": "concept", "title": "Preboarding communication"}, {"id": "f5f88abd-586e-440a-9b34-007d3f0194b7", "type": "concept", "title": "First-day readiness"}, {"id": "ecfe59db-6bcc-4649-9f48-962ff95a8a97", "type": "concept", "title": "New-hire experience"}], "description": "Students learn where recruiting ends and employment experience begins."}]}, {"id": "5ffac337-6f42-4e51-89f2-eff18d41594f", "type": "topic", "title": "AI-Assisted Hiring, Algorithmic Bias, and Auditability", "description": "The workbook rightly flags AI-assisted hiring as a required modern topic. Students learn how automated tools can help and harm recruiting, and how HR should govern them before trusting their outputs.", "children": [{"id": "9743f5b8-589d-4111-a97e-4d577c855a50", "type": "subtopic", "title": "AI use cases in recruiting", "children": [{"id": "cfd69d54-92d9-48dd-8816-71ba07064826", "type": "concept", "title": "Resume screening"}, {"id": "01bc6f9c-c03c-45f9-99a8-448a95374364", "type": "concept", "title": "Candidate matching"}, {"id": "26aea7e3-b874-45c8-92e3-69d493e2d66d", "type": "concept", "title": "Chatbots"}, {"id": "36f6b47a-ab87-4ad9-b413-8abe5d485320", "type": "concept", "title": "Interview analysis"}, {"id": "c688aaff-7e1c-41d4-85d5-f45fe3ee042d", "type": "concept", "title": "Sourcing recommendations"}, {"id": "f1293688-f8b5-413b-b531-5f923fbf7cef", "type": "concept", "title": "Scheduling automation"}], "description": "Students learn what tools do and where humans remain accountable."}, {"id": "f4f63a3a-7954-4fbe-866e-383e2d5bde91", "type": "subtopic", "title": "Bias, accessibility, and legal risk", "children": [{"id": "d86606b9-8bfe-4e1e-9c38-08439856d772", "type": "concept", "title": "Training data"}, {"id": "cafa6359-8021-40e8-b39f-1a8f5f41d002", "type": "concept", "title": "Proxy variables"}, {"id": "90e25a7b-5313-4f2f-ba49-f57ce0742509", "type": "concept", "title": "Disability accommodation"}, {"id": "1ef2938c-afd2-4405-b9de-e1aa7175d36a", "type": "concept", "title": "Language bias"}, {"id": "8a2523ee-f162-481f-a47b-a76ce9a6616f", "type": "concept", "title": "Disparate impact"}, {"id": "3fd96124-9019-4a51-84a1-a60cadc449d9", "type": "concept", "title": "Vendor claims"}], "description": "This subtopic examines how tools can reproduce historical bias or create new barriers."}, {"id": "9838c128-c833-43b2-a7bf-49c51acf142a", "type": "subtopic", "title": "Governance and auditability", "children": [{"id": "ab6f3774-cc6d-4cf9-a972-cd83533768a4", "type": "concept", "title": "Vendor due diligence"}, {"id": "b2962110-6827-4950-a14e-69fb82207c81", "type": "concept", "title": "Validation evidence"}, {"id": "1dad8914-8f60-442d-859e-55702d3cf9c6", "type": "concept", "title": "Human review"}, {"id": "e4e4982c-5796-4e4e-8005-d6e44019e4c1", "type": "concept", "title": "Audit logs"}, {"id": "5ec4ccfa-aabc-4af1-b1d7-00a776dd4acb", "type": "concept", "title": "Explainability"}, {"id": "ba735f1e-58f2-4a49-826f-ced03dd6a0fe", "type": "concept", "title": "Candidate notice"}], "description": "Students learn practical controls for responsible use of hiring technology."}]}, {"id": "9c8ad582-5bd4-4d47-97f9-0aefcc183e36", "type": "topic", "title": "Staffing Plan Project and Hiring Decision Communication", "description": "The capstone requires students to synthesize workforce planning, job analysis, sourcing, assessment, analytics, compliance, candidate experience, and AI governance into a professional staffing recommendation.", "children": [{"id": "1ff055ac-f9c7-4e93-bcf3-1bf064897e40", "type": "subtopic", "title": "Staffing problem diagnosis", "children": [{"id": "00bc44ee-2605-47b9-8d97-0cc63dba5f05", "type": "concept", "title": "Role context"}, {"id": "e663a7ab-1010-4a0a-8922-a7ee9b5a85b8", "type": "concept", "title": "Stakeholder goals"}, {"id": "d7d98c0b-30e4-489e-851d-3645abde73a5", "type": "concept", "title": "Labor-market constraints"}, {"id": "81993ec7-c7ad-4cc2-a8ae-ea205166fd0d", "type": "concept", "title": "Diversity goals"}, {"id": "44db5dcf-9041-478d-8beb-ad5a0070b8a8", "type": "concept", "title": "Hiring volume"}, {"id": "4198b1fd-9d1d-4e3e-9fab-ff5854a2cd63", "type": "concept", "title": "Risk analysis"}], "description": "Students learn to define the talent problem before proposing tactics."}, {"id": "3936dac9-225b-4f3a-ae5a-e99fea74f2e5", "type": "subtopic", "title": "Integrated staffing plan", "children": [{"id": "76aa3bce-e2ec-4ea3-b593-73babcce2c3c", "type": "concept", "title": "Sourcing mix"}, {"id": "82a884ff-1ed6-4954-8257-1b351d32e8a4", "type": "concept", "title": "Selection stages"}, {"id": "ffb37fe0-7262-44e4-a6ce-3e7dd3a0dad9", "type": "concept", "title": "Interview guides"}, {"id": "381ed558-87a1-4543-b827-ff7729212120", "type": "concept", "title": "Assessment plan"}, {"id": "2517c3af-1826-4af7-9120-52627bbc7c8d", "type": "concept", "title": "Timeline"}, {"id": "8a3a49eb-c9d7-4715-aa78-e94fbe63f6dc", "type": "concept", "title": "Metrics"}], "description": "This subtopic turns course tools into a coherent plan that a hiring team could actually use."}, {"id": "aa15284d-e5ad-4cad-aab3-03d0573a4dde", "type": "subtopic", "title": "Executive communication", "children": [{"id": "196e0ff7-fd0a-4367-861c-ee308a1c9ab2", "type": "concept", "title": "Decision memo"}, {"id": "6899aa9d-f3c1-4a53-baf9-c959d326d3d8", "type": "concept", "title": "Tradeoffs"}, {"id": "cf9ed298-2d37-477f-a3c8-ea384ab3c838", "type": "concept", "title": "Assumptions"}, {"id": "28156a53-7694-4195-b95a-83c705cf9420", "type": "concept", "title": "Implementation steps"}, {"id": "60d9fce0-0b9b-4acc-8b0d-0f249831b200", "type": "concept", "title": "Governance checks"}, {"id": "9abfd90e-0b8f-4f4c-9247-712f0f47702b", "type": "concept", "title": "Success measures"}], "description": "Students practice explaining hiring recommendations concisely and defensibly."}]}], "dbBacked": true}$rseljson$::jsonb,
